Section SIDE.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.

  Definition dof_side (LF : list fframe) (m0 m : mem) (lo shi ff fp P E vp n : Z) : Prop :=
    as_RFS H ((2, ff, fp) :: LF) m /\ pside2 m lo shi [(P, 80); (E, 24); (vp, n)] [(E, 24)]
    /\ aapp P 80 /\ aapp E 24 /\ aapp vp n /\ 0 <= n /\ fsobj H LF P 80 /\ fsobj H LF E 24 /\ fsobj H LF vp n
    /\ as_RFS H LF m0.                                   (* [comment removed for export] *)

  (* [comment removed for export] *)
  Definition dwin (ff P E : Z) (iv : Z * Z) : Prop :=
    aceil <= fst iv \/ (ff <= fst iv /\ snd iv <= ff + 256) \/ (P <= fst iv /\ snd iv <= P + 80) \/ (E <= fst iv /\ snd iv <= E + 24)
    \/ iv = (AG_HTTP_CAT, AG_HTTP_CAT + 64).

  (* [comment removed for export] *)
  Lemma dof_ff_nums : forall LF m0 m lo shi ff fp P E vp n,
    dof_side LF m0 m lo shi ff fp P E vp n ->
    fresh_frame H LF 2 ff fp /\ aapp ff 256
    /\ 6848512 <= ff /\ ff + 256 <= aceil /\ ff mod 8 = 0 /\ 6815744 <= fp /\ fp + 1 <= ff
    /\ 2148302336 <= Z.shiftr ff 3 + 2147450880 /\ Z.shiftr ff 3 + 2147450880 + 32 <= 17594333495296
    /\ Z.shiftr ff 3 + 2147450880 = sh ff
    /\ (ff + 256 <= 2147446784 \/ 17594333495296 <= ff)
    /\ (fp + 1 <= 2147446784 \/ 17594333495296 <= fp)
    /\ ff mod 32 = 0.
