  (* [comment removed for export] *)
  Lemma dof_obj_sep : forall LF m0 m lo shi ff fp P E vp n,
    dof_side LF m0 m lo shi ff fp P E vp n ->
       (P + 80 <= ff \/ ff + 256 <= P) /\ (E + 24 <= ff \/ ff + 256 <= E) /\ (vp + n <= ff \/ ff + 256 <= vp)
    /\ (P + 80 <= fp \/ fp + 1 <= P) /\ (E + 24 <= fp \/ fp + 1 <= E) /\ (vp + n <= fp \/ fp + 1 <= vp)
    /\ (sh P + nsh 80 <= sh ff \/ sh ff + 32 <= sh P) /\ (sh E + nsh 24 <= sh ff \/ sh ff + 32 <= sh E) /\ (sh vp + nsh n <= sh ff \/ sh ff + 32 <= sh vp).
