Ltac dwin_tac STK :=
  repeat apply Forall_cons; try apply Forall_nil; unfold dwin; cbn [fst snd];
  first [ right; right; right; right; unfold AG_HTTP_CAT; f_equal; clear; lia
        | right; right; right; left; clear; lia
        | right; right; left; clear; lia
        | right; left; clear; lia
        | left; first [assumption | STK] ].

