Ltac fe_tac TAC :=
  repeat (apply Forall_cons; [ cbn [fst snd]; solve [ repeat (first [ apply Exists_cons_hd; cbn [fst snd]; TAC | apply Exists_cons_tl ]) ] | ]);
  apply Forall_nil.
(* [comment removed for export] *)
Ltac munch_into MUt MU1 TAC :=
  unfold parked in MUt;
  let K := fresh "MUt" in
  pose proof (munch_compose _ _ _ _ _ MUt MU1 ltac:(fe_tac TAC)) as K; clear MUt; rename K into MUt.

