Ltac post_callZt segs m TAC :=
  let ms' := fresh "ms'" in let PO := fresh "PO" in
  intros ms' PO;
  (let h := head_of ltac:(type of PO) in try unfold h in PO);
  rewrite ?unsigned_lit in PO by TAC; rewrite ?Z.add_0_r in PO; revert ms' PO; post_call segs m.
Tactic Notation "callZt" uconstr(SPEC) tactic3(CLR) tactic3(TAC) :=
  lazymatch goal with
  | |- evt ?segs _ (MS _ _ _ _ _ ?m _) => eapply evt_cut; [ eapply SPEC | CLR; post_callZt segs m TAC ]
  end.

