  Definition dof_cont (Q : machine_state -> Prop) (pc : Z) (rax spx gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word)
      (F : bvmap 5 word) (fc : bv 32) (m1 : mem) : Prop :=
    forall t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6',
      evt asegs Q (MS (mkR rax spx gp tp t0' t1' t2' s0 s1 a0' a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6')
                      F (Z_to_bv 64 pc) fc None m1 (seg_rom asegs)).
